/* cs-location.js
 * ─────────────────────────────────────────────────────────────
 * Location section — wires input, detect button, prefs checkboxes
 * Depends on: LBLocation (lb-location.js must load first)
 * Called from: clock-settings.html → <script>csLocInit()</script>
 * ─────────────────────────────────────────────────────────────
 * TOC
 *   1. csLocInit — DOM wiring entry point
 *   2. locLoad — read stored location + prefs
 *   3. _syncDeps — dim dependent cells when GPS detect is off
 *   4. locSavePrefs — persist all four prefs
 *   5. detect button — geolocation + reverse geocode
 * ─────────────────────────────────────────────────────────────
 * refactor note: at folder pass move to app/ or settings/
 * ─────────────────────────────────────────────────────────────
 */

function csLocInit() {

  const elLabel   = document.getElementById('loc-label')
  const elCoords  = document.getElementById('loc-coords')
  const elStatus  = document.getElementById('loc-status')
  const elDetect  = document.getElementById('loc-detect')
  const elDetPref = document.getElementById('loc-pref-detect')
  const depCells  = document.querySelectorAll('.loc-dep-cell')

  // ── 2. load stored state ──────────────────────────────────

  function locLoad() {
    const loc   = LBLocation.get()
    const prefs = LBLocation.getPrefs()

    if (loc) {
      elLabel.value         = loc.label || ''
      elCoords.textContent  = `${loc.lat.toFixed(2)}° ${loc.lon.toFixed(2)}°`
    }

    elDetPref.checked = prefs.detect
    document.getElementById('loc-pref-weather').checked  = prefs.weather
    document.getElementById('loc-pref-sunmoon').checked  = prefs.sunmoon
    document.getElementById('loc-pref-tz').checked       = prefs.tz

    _syncDeps()
  }

  // ── 3. dim dependent cells ────────────────────────────────

  function _syncDeps() {
    const on = elDetPref.checked
    depCells.forEach(cell => cell.classList.toggle('loc-disabled', !on))
  }

  // ── 4. save prefs ─────────────────────────────────────────

  function locSavePrefs() {
    LBLocation.setPrefs({
      detect:  elDetPref.checked,
      weather: document.getElementById('loc-pref-weather').checked,
      sunmoon: document.getElementById('loc-pref-sunmoon').checked,
      tz:      document.getElementById('loc-pref-tz').checked,
    })
  }

  // ── wire checkboxes ───────────────────────────────────────

  elDetPref.addEventListener('change', () => { _syncDeps(); locSavePrefs() })
  depCells.forEach(cell => {
    cell.querySelector('input')?.addEventListener('change', locSavePrefs)
  })

  // ── save manual label ─────────────────────────────────────

  elLabel.addEventListener('change', () => {
    const loc = LBLocation.get() || {}
    LBLocation.set({ ...loc, label: elLabel.value.trim() })
  })

  // ── 5. detect button ──────────────────────────────────────

  elDetect.addEventListener('click', async () => {
    elStatus.textContent  = 'detecting…'
    elDetect.disabled     = true
    try {
      const loc = await LBLocation.detect()
      elCoords.textContent = `${loc.lat.toFixed(2)}° ${loc.lon.toFixed(2)}°`
      elStatus.textContent = `detected · ${Math.round(loc.accuracy ?? 0)}m accuracy`

      if (!elLabel.value.trim()) {
        elStatus.textContent += ' · looking up city…'
        try {
          const label = await LBLocation.reverseGeocode(loc.lat, loc.lon)
          if (label) {
            elLabel.value = label
            LBLocation.set({ ...LBLocation.get(), label })
            elStatus.textContent = `detected · ${label}`
          }
        } catch {}
      }
    } catch (e) {
      // there IS no GPS prompt inside the webview — WKWebView on macOS has no
      // permission plumbing for navigator.geolocation, so it auto-denies.
      // fall back to the IP chain (same providers as geo.js): city-level, keyless.
      elStatus.textContent = 'no GPS in the webview — using network location…'
      try {
        let g = null
        for (const url of ['https://ipapi.co/json/', 'https://ipwho.is/']) {
          try { g = await fetch(url).then(r => r.json()); if (g && (g.latitude ?? g.lat) != null) break } catch {}
        }
        const lat = g?.latitude ?? g?.lat, lon = g?.longitude ?? g?.lon
        if (lat == null) throw new Error('no provider answered')
        const label = [g.city, g.region_code || g.region].filter(Boolean).join(', ')
        LBLocation.set({ ...LBLocation.get(), lat, lon, accuracy: 5000, label: elLabel.value.trim() || label })
        elCoords.textContent = `${lat.toFixed(2)}° ${lon.toFixed(2)}°`
        if (!elLabel.value.trim() && label) elLabel.value = label
        elStatus.textContent = `located by network · ${label || 'city-level'}`
      } catch {
        elStatus.textContent = 'detection failed — type your city instead'
      }
    }
    elDetect.disabled = false
  })

  locLoad()
}
